make_counter <- function() {
  count <- 0
  function() {
    count <<- count + 1      # modifies the enclosing binding
    count
  }
}
counter <- make_counter()
for (i in 1:2) counter()
print(counter())                          #> [1] 3
print(get("count", environment(counter))) #> [1] 3

x <- "global"
f <- function() x
g <- function() { x <- "local to g"; f() }
print(g())                                #> [1] "global" (lexical)

cache <- new.env()
remember <- function(env, key, val) assign(key, val, envir = env)
remember(cache, "a", 1)
print(ls(cache))                          #> [1] "a" (no copy made)
print(environmentName(parent.env(globalenv())) != "")  #> [1] TRUE

safe_log <- function(x) {
  tryCatch({
    if (!is.numeric(x)) stop(errorCondition("need a number", class = "typeError"))
    log(x)
  },
  typeError = function(e) { message("type problem: ", conditionMessage(e)); NA },
  warning = function(w) { message("warning caught: ", conditionMessage(w)); NaN })
}
print(safe_log(100))       #> [1] 4.60517
print(safe_log("a"))       #> type problem: need a number / [1] NA
print(safe_log(-1))        #> warning caught: NaNs produced / [1] NaN

res <- withCallingHandlers(
  { warning("first"); "kept going" },
  warning = function(w) { message("logged: ", conditionMessage(w))
                          invokeRestart("muffleWarning") })
print(res)                 #> logged: first / [1] "kept going"

